package com.jobradar.taxonomy.role;
import com.jobradar.taxonomy.common.TaxonomyEntity; import com.jobradar.taxonomy.category.CategoryEntity; import jakarta.persistence.*;
@Entity @Table(name="job_roles") public class RoleEntity extends TaxonomyEntity { @Column(name="role_name",nullable=false,length=120) private String roleName; @Column(nullable=false,length=140) private String slug; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="category_id",nullable=false) private CategoryEntity category; protected RoleEntity(){} public RoleEntity(String n,String s,CategoryEntity c){roleName=n;slug=s;category=c;} public String getRoleName(){return roleName;} public String getSlug(){return slug;} public CategoryEntity getCategory(){return category;} public void update(String n,String s,CategoryEntity c){roleName=n;slug=s;category=c;} }
